{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@happycastle/opencode-litellm",
  "version": "0.8.0",
  "description": "OpenCode plugin for LiteLLM proxy support with auto-detection and dynamic model discovery",
  "type": "module",
  "main": "./dist/index.mjs",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.mjs"
    },
    "./cli": "./dist/opencode-litellm.mjs"
  },
  "bin": {
    "opencode-litellm": "dist/opencode-litellm.mjs",
    "codex-litellm": "dist/opencode-litellm.mjs"
  },
  "engines": {
    "node": "^22.22.2 || ^24.12.0 || >=26.0.0"
  },
  "publishConfig": {
    "access": "public"
  },
  "files": [
    "src",
    "dist",
    "skills",
    "LICENSE"
  ],
  "scripts": {
    "test": "npm run build && bun test",
    "typecheck": "tsc --noEmit",
    "clean": "node scripts/clean-dist.mjs",
    "build": "node scripts/build.mjs",
    "prepare": "npm run build",
    "test:git-install": "node scripts/verify-git-install.mjs"
  },
  "keywords": [
    "opencode",
    "litellm",
    "lite-llm",
    "plugin",
    "llm-proxy",
    "openai-compatible"
  ],
  "author": "happycastle114 (https://github.com/happycastle114)",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/happycastle114/opencode-litellm.git"
  },
  "bugs": {
    "url": "https://github.com/happycastle114/opencode-litellm/issues"
  },
  "homepage": "https://github.com/happycastle114/opencode-litellm#readme",
  "dependencies": {
    "@opencode-ai/plugin": "1.18.31",
    "@opencode-ai/sdk": "1.18.31",
    "jsonc-parser": "3.3.1",
    "proper-lockfile": "4.1.2",
    "smol-toml": "1.8.0"
  },
  "devDependencies": {
    "@types/node": "^25.0.3",
    "@types/proper-lockfile": "4.1.4",
    "bun": "1.3.14",
    "typescript": "^5.9.3"
  },
  "gitHead": "3d26a84976b64b6131bad612635b81f366a54ce7"
}
